previewCss:
.darma-loader-darma-b10-flag-wave { --accent: var(--loader-color, #1d4ed8); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b10-flag-wave .darma-loader-darma-b10-flag-wave__pole { position: absolute; left: 24%; top: 8%; width: calc(var(--loader-size, 84px) * .04); height: 84%; background: linear-gradient(#cbd5e1, #64748b); border-radius: 3px; }
.darma-loader-darma-b10-flag-wave .darma-loader-darma-b10-flag-wave__flag { position: absolute; left: 26%; top: 12%; width: 50%; height: 32%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); border-radius: 0 4px 4px 0; transform-origin: left center; animation: darma-loader-darma-b10-flag-wave-wave calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b10-flag-wave-wave { 0%, 100% { transform: rotate(-1.5deg) skewY(4deg); border-radius: 0 4px 30% 4px; } 25% { transform: rotate(1.5deg) skewY(-5deg); border-radius: 0 4px 4px 30%; } 50% { transform: rotate(-1.5deg) skewY(4deg); border-radius: 0 30% 4px 4px; } 75% { transform: rotate(1deg) skewY(-3deg); } }

